platform.apilevel = '2.0'

-- ==========================================================
--  Generated by tools/bundle.py -- do not edit this file.
--  Sources: src/snake/game.lua, src/snake/main.lua
-- ==========================================================

local Game = (function()
-- game.lua -- pure Snake game logic.
--
-- This module deliberately knows nothing about the TI-Nspire: no `platform`,
-- no `gc`, no `timer`. That keeps it runnable under a plain Lua 5.1
-- interpreter on a laptop, so the rules can be tested without a calculator.
-- All drawing and input lives in src/main.lua.

local Game = {}
Game.__index = Game

local DIRS = {
  up    = { x =  0, y = -1 },
  down  = { x =  0, y =  1 },
  left  = { x = -1, y =  0 },
  right = { x =  1, y =  0 },
}
Game.DIRS = DIRS

local START_LEN       = 4   -- segments the snake starts with
local GROW_PER_FOOD   = 2   -- segments gained per apple
local FOODS_PER_LEVEL = 4   -- apples needed to speed up
local QUEUE_MAX       = 3   -- buffered turns, so fast double-taps register

-- Ticks of the host timer to wait between moves, indexed by level. The host
-- runs a fixed fast timer and counts ticks rather than restarting the timer
-- at a new interval, because timer granularity varies between Nspire OSes.
local STEP_TICKS = { 4, 4, 3, 3, 2, 2, 2, 1, 1, 1 }

Game.MAX_LEVEL = #STEP_TICKS
Game.START_LEN = START_LEN
Game.GROW_PER_FOOD = GROW_PER_FOOD
Game.FOODS_PER_LEVEL = FOODS_PER_LEVEL

-- cols, rows: playfield size in cells.
-- opts.rand:      function(n) -> integer in [1, n]. Injectable for tests.
-- opts.wrap:      true = edges wrap around, false = edges kill.
-- opts.highScore: carried across rounds.
function Game.new(cols, rows, opts)
  opts = opts or {}
  local self = setmetatable({}, Game)
  self.cols = cols
  self.rows = rows
  self.rand = opts.rand or function(n) return math.random(n) end
  self.wrap = opts.wrap or false
  self.highScore = opts.highScore or 0
  self:reset()
  return self
end

-- Cells are stored in a deque (`cells` indexed by `tail`..`head`) rather than
-- an array we shift, so growing the snake stays O(1) per move even when it is
-- hundreds of segments long. `occupied` mirrors it as a set for O(1) hit tests.
function Game:cellKey(x, y)
  return (y - 1) * self.cols + x
end

function Game:length()
  return self.head - self.tail + 1
end

function Game:pushFront(x, y)
  self.head = self.head + 1
  self.cells[self.head] = { x = x, y = y }
  self.occupied[self:cellKey(x, y)] = true
end

function Game:popBack()
  local c = self.cells[self.tail]
  self.cells[self.tail] = nil
  self.tail = self.tail + 1
  self.occupied[self:cellKey(c.x, c.y)] = nil
  return c
end

-- Segments head-first. Convenient for tests; the renderer walks the deque
-- directly to avoid allocating a table every frame.
function Game:segments()
  local out = {}
  for i = self.head, self.tail, -1 do
    out[#out + 1] = self.cells[i]
  end
  return out
end

function Game:reset()
  self.cells = {}
  self.occupied = {}
  self.head, self.tail = 0, 1 -- empty deque: length == 0
  self.queue = {}
  self.growth = 0
  self.score = 0
  self.foodEaten = 0
  self.level = 1
  self.state = "ready" -- ready | playing | paused | over | won
  self.dir = DIRS.right

  local cy = math.ceil(self.rows / 2)
  local sx = math.max(START_LEN, math.floor(self.cols / 4))
  -- Build tail-first so the final pushFront leaves the head at sx.
  for i = START_LEN - 1, 0, -1 do
    self:pushFront(sx - i, cy)
  end

  self:spawnFood()
end

-- Places food on a random free cell. Rejection sampling is fast while the
-- board is mostly empty; once it fills up we index directly into the free
-- cells instead, so a nearly-complete game can't spin here.
function Game:spawnFood()
  local total = self.cols * self.rows
  local free = total - self:length()
  if free <= 0 then
    self.food = nil
    return false
  end

  if free > total * 0.25 then
    for _ = 1, 40 do
      local x, y = self.rand(self.cols), self.rand(self.rows)
      if not self.occupied[self:cellKey(x, y)] then
        self.food = { x = x, y = y }
        return true
      end
    end
  end

  local n = self.rand(free)
  for y = 1, self.rows do
    for x = 1, self.cols do
      if not self.occupied[self:cellKey(x, y)] then
        n = n - 1
        if n == 0 then
          self.food = { x = x, y = y }
          return true
        end
      end
    end
  end

  self.food = nil
  return false
end

function Game:ticksPerStep()
  return STEP_TICKS[self.level] or 1
end

function Game:start()
  if self.state == "ready" then self.state = "playing" end
end

function Game:pause()
  if self.state == "playing" then self.state = "paused" end
end

function Game:resume()
  if self.state == "paused" then self.state = "playing" end
end

function Game:isOver()
  return self.state == "over" or self.state == "won"
end

function Game:recordScore()
  if self.score > self.highScore then self.highScore = self.score end
end

-- Queues a turn. Reversals are rejected against the last *queued* direction
-- rather than the current one, so pressing up-then-right inside a single tick
-- turns the corner instead of the second press being read as a reversal.
function Game:setDirection(name)
  local d = DIRS[name]
  if not d then return false end
  if self.state ~= "playing" then return false end
  if #self.queue >= QUEUE_MAX then return false end

  local last = self.queue[#self.queue] or self.dir
  if d.x == last.x and d.y == last.y then return false end
  if self:length() > 1 and d.x == -last.x and d.y == -last.y then return false end

  self.queue[#self.queue + 1] = d
  return true
end

function Game:step()
  if self.state ~= "playing" then return end

  if #self.queue > 0 then
    self.dir = table.remove(self.queue, 1)
  end

  local h = self.cells[self.head]
  local nx, ny = h.x + self.dir.x, h.y + self.dir.y

  if self.wrap then
    if nx < 1 then nx = self.cols elseif nx > self.cols then nx = 1 end
    if ny < 1 then ny = self.rows elseif ny > self.rows then ny = 1 end
  elseif nx < 1 or nx > self.cols or ny < 1 or ny > self.rows then
    self.state = "over"
    self:recordScore()
    return
  end

  -- The tail cell is fair game when the tail is about to vacate it this move,
  -- which is what lets the snake follow its own tail without dying.
  local vacating = (self.growth == 0) and self:length() > 1
  local tailCell = self.cells[self.tail]
  local blocked = self.occupied[self:cellKey(nx, ny)] or false
  if blocked and vacating and nx == tailCell.x and ny == tailCell.y then
    blocked = false
  end
  if blocked then
    self.state = "over"
    self:recordScore()
    return
  end

  if vacating then
    self:popBack()
  elseif self.growth > 0 then
    self.growth = self.growth - 1
  end
  self:pushFront(nx, ny)

  if self.food and nx == self.food.x and ny == self.food.y then
    self.growth = self.growth + GROW_PER_FOOD
    self.foodEaten = self.foodEaten + 1
    self.score = self.score + 10 * self.level
    self.level = math.min(Game.MAX_LEVEL, 1 + math.floor(self.foodEaten / FOODS_PER_LEVEL))
    if not self:spawnFood() then
      self.state = "won"
      self:recordScore()
    end
  end
end

return Game
end)()

-- main.lua -- TI-Nspire presentation layer: drawing, input, timing.
--
-- Rules live in src/game.lua. `platform.apilevel` is emitted as the first line
-- of the bundle by tools/bundle.py, so it is intentionally absent here.
--
-- When bundled, `Game` is already a local from the inlined module; the
-- `Game or require` form below also lets this file load under a desktop Lua.
local Game = Game or require("game")

local HUD_H    = 22    -- height of the score bar, pixels
local CELL_MIN = 6     -- below this the snake is hard to see
local BASE_TICK = 0.05 -- host timer period; Game:ticksPerStep() sets the pace

local ui = { w = 318, h = 212, cell = 8, cols = 34, rows = 21, ox = 0, oy = HUD_H }
local game = Game.new(ui.cols, ui.rows)

local ticks   = 0 -- timer ticks since the last snake move
local blink   = 0 -- drives the blinking prompt on overlay screens
local entropy = 0 -- ticks the player idled before starting; seeds the RNG

-- ---------------------------------------------------------------- helpers --

-- os.time() alone is a poor seed here: a handheld that has just been reset can
-- report the same value every launch, which would deal the same apples every
-- game. Mixing in how long the player sat on the title screen fixes that.
local function reseed()
  local t = 0
  if os and os.time then t = os.time() or 0 end
  if os and os.clock then t = t + math.floor((os.clock() or 0) * 1000) end
  math.randomseed(t + entropy * 7919)
  math.random(); math.random() -- first draws after a reseed are weakly mixed
end

local function newRound()
  reseed()
  game:reset()
  ticks = 0
end

local function confirm()
  local s = game.state
  if s == "ready" then
    newRound()
    game:start()
  elseif s == "paused" then
    game:resume()
  elseif game:isOver() then
    newRound()
    game:start()
  end
end

local function togglePause()
  if game.state == "playing" then
    game:pause()
  elseif game.state == "paused" then
    game:resume()
  end
end

-- --------------------------------------------------------------- lifecycle --

-- Called before the first paint, and again if the window is resized (which on
-- a handheld means never, but the computer software can resize freely).
function on.resize(w, h)
  ui.w, ui.h = w, h

  local fieldW = w - 8
  local fieldH = h - HUD_H - 8
  local cell = math.floor(math.min(fieldW / 34, fieldH / 21))
  if cell < CELL_MIN then cell = CELL_MIN end

  local cols = math.max(10, math.floor(fieldW / cell))
  local rows = math.max(8, math.floor(fieldH / cell))

  ui.cell, ui.cols, ui.rows = cell, cols, rows
  ui.ox = math.floor((w - cols * cell) / 2)
  ui.oy = HUD_H + math.floor((h - HUD_H - rows * cell) / 2)

  -- Only rebuild when the grid actually changed; a cosmetic resize shouldn't
  -- throw away a game in progress.
  if game.cols ~= cols or game.rows ~= rows then
    game = Game.new(cols, rows, { highScore = game.highScore, wrap = game.wrap })
  end
  platform.window:invalidate()
end

timer.start(BASE_TICK)

function on.timer()
  blink = blink + 1
  local dirty = false

  if game.state == "playing" then
    ticks = ticks + 1
    if ticks >= game:ticksPerStep() then
      ticks = 0
      game:step()
      dirty = true
    end
  else
    entropy = entropy + 1
    if blink % 8 == 0 then dirty = true end
  end

  if dirty then platform.window:invalidate() end
end

function on.deactivate()
  game:pause()
  platform.window:invalidate()
end

-- ------------------------------------------------------------------- input --

function on.arrowKey(key)
  if game.state == "ready" then
    newRound()
    game:start()
  end
  game:setDirection(key)
  platform.window:invalidate()
end

function on.enterKey()
  confirm()
  platform.window:invalidate()
end

function on.escapeKey()
  togglePause()
  platform.window:invalidate()
end

local CHAR_DIRS = {
  w = "up",   ["8"] = "up",
  s = "down", ["2"] = "down",
  a = "left", ["4"] = "left",
  d = "right",["6"] = "right",
}

function on.charIn(ch)
  ch = string.lower(ch or "")
  local dir = CHAR_DIRS[ch]

  if dir then
    on.arrowKey(dir)
    return
  elseif ch == " " then
    confirm()
  elseif ch == "p" then
    togglePause()
  elseif ch == "r" then
    newRound()
    game:start()
  elseif ch == "m" and game.state ~= "playing" then
    -- Wall mode is a property of the round, so only offer it between rounds.
    game.wrap = not game.wrap
    if game:isOver() then newRound() end
  end

  platform.window:invalidate()
end

-- Steering by click, for the touchpad and for mouse play in the computer
-- software: move toward whichever axis the click is furthest along from the head.
function on.mouseDown(x, y)
  if game.state ~= "playing" then
    confirm()
  else
    local h = game.cells[game.head]
    local hx = ui.ox + (h.x - 0.5) * ui.cell
    local hy = ui.oy + (h.y - 0.5) * ui.cell
    local dx, dy = x - hx, y - hy
    if math.abs(dx) > math.abs(dy) then
      game:setDirection(dx < 0 and "left" or "right")
    else
      game:setDirection(dy < 0 and "up" or "down")
    end
  end
  platform.window:invalidate()
end

-- ----------------------------------------------------------------- drawing --

local function drawHud(gc)
  gc:setColorRGB(30, 34, 44)
  gc:fillRect(0, 0, ui.w, HUD_H)
  gc:setColorRGB(58, 64, 80)
  gc:drawLine(0, HUD_H - 1, ui.w, HUD_H - 1)

  gc:setFont("sansserif", "b", 10)
  local labelW = gc:getStringWidth("SNAKE")

  gc:setFont("sansserif", "r", 10)
  local stats = "Score " .. game.score
    .. "   Len " .. game:length()
    .. "   Lv " .. game.level
    .. "   Best " .. game.highScore
  local statsW = gc:getStringWidth(stats)
  local statsX = ui.w - statsW - 6

  -- Big scores, or a narrower font than we assumed, can push the stats into
  -- the title. The stats matter more, so the title yields.
  if statsX > labelW + 12 then
    gc:setFont("sansserif", "b", 10)
    gc:setColorRGB(120, 230, 130)
    gc:drawString("SNAKE", 6, 4, "top")
    gc:setFont("sansserif", "r", 10)
  end

  gc:setColorRGB(215, 220, 232)
  gc:drawString(stats, math.max(4, statsX), 4, "top")
end

local function drawField(gc)
  local ox, oy, cell = ui.ox, ui.oy, ui.cell
  local pw, ph = game.cols * cell, game.rows * cell

  gc:setColorRGB(12, 14, 19)
  gc:fillRect(ox, oy, pw, ph)

  -- A dashed border is the visual tell that edges wrap instead of kill.
  gc:setPen("thin", game.wrap and "dashed" or "smooth")
  gc:setColorRGB(70, 78, 96)
  gc:drawRect(ox - 1, oy - 1, pw + 1, ph + 1)
  gc:setPen("thin", "smooth")

  if game.food then
    local fx = ox + (game.food.x - 1) * cell
    local fy = oy + (game.food.y - 1) * cell
    gc:setColorRGB(228, 72, 62)
    gc:fillArc(fx + 1, fy + 1, cell - 2, cell - 2, 0, 360)
  end

  -- Body shades from bright at the head to dark at the tail. The ramp is
  -- quantised into bands so a long snake needs ~8 setColorRGB calls, not 800.
  local n = math.max(1, game:length() - 1)
  local i, band = 0, -1
  for idx = game.head, game.tail, -1 do
    local c = game.cells[idx]
    local x = ox + (c.x - 1) * cell
    local y = oy + (c.y - 1) * cell

    if idx == game.head then
      gc:setColorRGB(158, 248, 158)
      band = -1
    else
      local b = math.floor((i / n) * 7)
      if b ~= band then
        band = b
        local t = b / 7
        gc:setColorRGB(
          math.floor(46 + 18 * (1 - t)),
          math.floor(206 - 96 * t),
          math.floor(112 - 46 * t))
      end
    end

    gc:fillRect(x, y, cell - 1, cell - 1)
    i = i + 1
  end

  -- Eyes, once the cells are big enough to fit them.
  if cell >= 7 then
    local h = game.cells[game.head]
    local hx = ox + (h.x - 1) * cell
    local hy = oy + (h.y - 1) * cell
    local d = game.dir
    local px = (d.x ~= 0) and (d.x > 0 and cell - 3 or 1) or 1
    local py = (d.y ~= 0) and (d.y > 0 and cell - 3 or 1) or 1
    gc:setColorRGB(16, 26, 18)
    if d.x ~= 0 then
      gc:fillRect(hx + px, hy + 1, 2, 2)
      gc:fillRect(hx + px, hy + cell - 4, 2, 2)
    else
      gc:fillRect(hx + 1, hy + py, 2, 2)
      gc:fillRect(hx + cell - 4, hy + py, 2, 2)
    end
  end
end

-- lines: array of { text, dim } -- dim entries blink on the overlay screens.
local function drawPanel(gc, title, lines, accent)
  gc:setFont("sansserif", "b", 16)
  local titleW = gc:getStringWidth(title)

  gc:setFont("sansserif", "r", 10)
  local maxW = titleW
  for _, l in ipairs(lines) do
    local lw = gc:getStringWidth(l[1])
    if lw > maxW then maxW = lw end
  end

  local pad, lineH = 12, 14
  -- Clamp to the window: the handheld is always wide enough, but the computer
  -- software can be resized smaller than the panel's natural size, and the
  -- Nspire clips silently rather than complaining.
  local bw = math.min(maxW + pad * 2, ui.w - 4)
  local bh = math.min(24 + #lines * lineH + pad * 2, ui.h - HUD_H - 4)
  local bx = math.max(2, math.floor((ui.w - bw) / 2))
  local by = math.max(HUD_H + 2, math.floor((ui.h - bh) / 2) + math.floor(HUD_H / 2))

  gc:setColorRGB(26, 30, 39)
  gc:fillRect(bx, by, bw, bh)
  gc:setColorRGB(accent[1], accent[2], accent[3])
  gc:drawRect(bx, by, bw, bh)

  gc:setFont("sansserif", "b", 16)
  gc:drawString(title, bx + math.floor((bw - titleW) / 2), by + pad - 2, "top")

  gc:setFont("sansserif", "r", 10)
  local y = by + pad + 22
  local lit = (blink % 16) < 10
  for _, l in ipairs(lines) do
    if l[2] and not lit then
      gc:setColorRGB(90, 96, 110)
    elseif l[2] then
      gc:setColorRGB(235, 238, 245)
    else
      gc:setColorRGB(186, 192, 206)
    end
    gc:drawString(l[1], bx + math.floor((bw - gc:getStringWidth(l[1])) / 2), y, "top")
    y = y + lineH
  end
end

local function drawOverlay(gc)
  local s = game.state
  if s == "ready" then
    drawPanel(gc, "SNAKE", {
      { "Arrows, 2/4/6/8 or WASD to steer" },
      { "esc or P pause     R restart" },
      { game.wrap and "Edges: wrap around   (M)" or "Edges: solid walls   (M)" },
      { "Press enter to play", true },
    }, { 120, 230, 130 })
  elseif s == "paused" then
    drawPanel(gc, "PAUSED", {
      { "Score " .. game.score .. "     Length " .. game:length() },
      { "Press enter to resume", true },
    }, { 240, 190, 70 })
  elseif s == "over" then
    drawPanel(gc, "GAME OVER", {
      { "Score " .. game.score .. "     Length " .. game:length() },
      { "Best " .. game.highScore },
      { "Press enter to play again", true },
    }, { 228, 72, 62 })
  elseif s == "won" then
    drawPanel(gc, "PERFECT!", {
      { "You filled the board." },
      { "Score " .. game.score },
      { "Press enter to play again", true },
    }, { 120, 230, 130 })
  end
end

function on.paint(gc)
  gc:setColorRGB(18, 21, 27)
  gc:fillRect(0, 0, ui.w, ui.h)
  drawField(gc)
  drawHud(gc)
  drawOverlay(gc)
end
